function blocked(x,y,r=9){return x<r||y<r||x>WORLD-r||y>WORLD-r||water(x,y,r)||buildings.some(b=>x>b.x-r&&x<b.x+b.w+r&&y>b.y-r&&y<b.y+b.h+r);}
// Circle against the rotated body, including a small wheel clearance.
function pedestrianContact(x,y,c,r=8){const ca=Math.cos(c.a),sa=Math.sin(c.a),dx=x-c.x,dy=y-c.y,lx=dx*ca+dy*sa,ly=-dx*sa+dy*ca,hx=c.type.w/2+2,hy=c.type.h/2+2;const qx=clamp(lx,-hx,hx),qy=clamp(ly,-hy,hy);let nx=lx-qx,ny=ly-qy,d=Math.hypot(nx,ny),depth;if(d>=r)return null;if(d>.0001){nx/=d;ny/=d;depth=r-d;}else{const ex=hx-Math.abs(lx),ey=hy-Math.abs(ly);if(ex<ey){nx=lx>=0?1:-1;ny=0;depth=ex+r;}else{nx=0;ny=ly>=0?1:-1;depth=ey+r;}}return {x:nx*ca-ny*sa,y:nx*sa+ny*ca,depth};}
function pedestrianBlocked(x,y,ignore=null){return blocked(x,y,8)||cars.some(c=>c!==ignore&&pedestrianContact(x,y,c));}
function movePedestrian(mx,my){let x=player.x+mx,y=player.y+my;for(let pass=0;pass<3;pass++)for(const c of cars){const h=pedestrianContact(x,y,c);if(!h)continue;const into=mx*h.x+my*h.y;if(into<0){mx-=into*h.x;my-=into*h.y;x=player.x+mx;y=player.y+my;}}if(!pedestrianBlocked(x,y)){player.x=x;player.y=y;return;}if(!pedestrianBlocked(player.x+mx,player.y))player.x+=mx;if(!pedestrianBlocked(player.x,player.y+my))player.y+=my;}
function resolvePedestrianCars(){if(player.car)return;for(let pass=0;pass<3;pass++){let touched=false;for(const c of cars){const hit=pedestrianContact(player.x,player.y,c);if(!hit)continue;touched=true;const speed=Math.abs(c.s);if(speed>45)hurt(speed*.09);const x=player.x+hit.x*(hit.depth+.05),y=player.y+hit.y*(hit.depth+.05);if(!pedestrianBlocked(x,y,c)){player.x=x;player.y=y;}else c.s=0;}if(!touched)break;}}
function carBlocked(c,x,y,a=c.a){const ca=Math.cos(a),sa=Math.sin(a),l=c.type.w/2,w=c.type.h/2;for(const [u,v] of [[-l,-w],[-l,w],[l,-w],[l,w],[0,0]])if(blocked(x+u*ca-v*sa,y+u*sa+v*ca,2))return true;return false;}
function pathPoint(ix,iy,dir){const x=OFFSET+ix*STEP,y=OFFSET+iy*STEP;return {x:x+(dir===1?-LANE:dir===3?LANE:0),y:y+(dir===0?LANE:dir===2?-LANE:0)};}
const dx=[1,0,-1,0],dy=[0,1,0,-1];
function setNext(c,dir){c.dir=dir;c.ix+=dx[dir];c.iy+=dy[dir];c.target=pathPoint(c.ix,c.iy,dir);}
function chooseNext(c){const opts=[c.dir,(c.dir+1)%4,(c.dir+3)%4].filter(d=>edgeValid(c.ix,c.iy,d));if(!opts.length){if(edgeValid(c.ix,c.iy,(c.dir+2)%4))opts.push((c.dir+2)%4);else{c.s=0;return;}}let dir=opts.includes(c.dir)&&Math.random()<.62?c.dir:opts[Math.floor(Math.random()*opts.length)];if(c.police&&wanted>0){dir=opts.reduce((best,d)=>{const p=pathPoint(c.ix+dx[d],c.iy+dy[d],d),q=pathPoint(c.ix+dx[best],c.iy+dy[best],best);return dist(p,player)<dist(q,player)?d:best;},opts[0]);}setNext(c,dir);}
