function spawnPed(){let p={x:0,y:0,a:rand(0,TAU),color:palette[Math.floor(rand(0,palette.length))],s:rand(18,35),panic:0,hp:40,step:rand(0,6)};for(let i=0;i<100;i++){p.x=rand(100,WORLD-100);p.y=rand(100,WORLD-100);if(!blocked(p.x,p.y,9)&&!onRoad(p.x,p.y)){peds.push(p);return;}}}for(let i=0;i<145;i++)spawnPed();
