function musicNote(note,at,duration,volume,type='triangle'){const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=440*Math.pow(2,(note-69)/12);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+duration);o.connect(g);g.connect(musicBus);rememberVoice(o);o.onended=()=>{musicVoices.delete(o);o.disconnect();g.disconnect();};o.start(at);o.stop(at+duration+.02);}
function drum(at,kick=false,snare=false){const g=audio.createGain();g.connect(musicBus);const o=kick?audio.createOscillator():audio.createBufferSource();if(kick){o.frequency.setValueAtTime(130,at);o.frequency.exponentialRampToValueAtTime(42,at+.15);o.connect(g);}else{o.buffer=noiseBuffer;const filter=audio.createBiquadFilter();filter.type='highpass';filter.frequency.value=snare?1500:6500;o.connect(filter);filter.connect(g);}const dur=kick?.18:snare?.12:.045;g.gain.setValueAtTime(kick?.13:snare?.075:.025,at);g.gain.exponentialRampToValueAtTime(.001,at+dur);rememberVoice(o);o.onended=()=>{musicVoices.delete(o);o.disconnect();g.disconnect();};o.start(at);o.stop(at+dur);}
