function nearestCar(){let best=null,d=64;for(const c of cars)if(c.hp>0){const dd=dist(c,player);if(dd<d){best=c;d=dd;}}return best;}
function action(){if(!active)return;if(player.car){const c=player.car;if(Math.abs(c.s)>110){toast('Zwolnij przed wysiadaniem.');return;}for(const side of [1,-1,2]){let a=c.a+Math.PI/2*side,x=c.x+Math.cos(a)*40,y=c.y+Math.sin(a)*40;if(!blocked(x,y,10)&&!cars.some(o=>o!==c&&Math.hypot(o.x-x,o.y-y)<26)){player.x=x;player.y=y;player.car=null;c.s*=.3;invincible=1;toast('Pieszo · mysz celuje, R zmienia broń');return;}}toast('Brak miejsca. Odsuń auto od przeszkody.');return;}let c=nearestCar();if(!c){toast('Podejdź bliżej sprawnego auta.');return;}if(c.ai)crime(c.police?1.2:.55);c.ai=false;c.parked=false;player.car=c;player.x=c.x;player.y=c.y;toast(c.type.name+' · Shift / HAMULEC = ręczny');tone(160,.12,'triangle');}
