function beginMission(id){const m=missionDefs.find(v=>v.id===id);if(!m)return;if(job&&job.id===id){closePanel();return;}job={id:m.id,index:0,time:m.time||Infinity,reward:m.reward,target:m.steps[0]};navRoute=roadRoute(player,job.target);navRefresh=clock+2;closePanel();if(m.id==='escape'){crime(Math.max(0,2-wanted));dispatchPatrol();dispatchPatrol();}toast(m.title+' · '+job.target.label);hud();}
