function drawAtlas(){const g=$('atlasCanvas').getContext('2d'),size=800,s=size/WORLD;g.drawImage(mapCanvas,0,0,size,size);g.fillStyle='#0b242a25';g.fillRect(0,0,size,size);g.lineJoin='round';if(job&&navRoute.length){g.strokeStyle='#ffe596';g.lineWidth=3;g.beginPath();navRoute.forEach((p,i)=>i?g.lineTo(p.x*s,p.y*s):g.moveTo(p.x*s,p.y*s));g.stroke();circle(g,job.target.x*s,job.target.y*s,8,'#f2bd65');}for(const l of landmarks){circle(g,l.x*s,l.y*s,3,'#faf0c8');const label=l.name;g.font='bold 10px Arial';g.textAlign='center';const width=g.measureText(label).width+10;rect(g,l.x*s-width/2,l.y*s-24,width,15,'#10241eef');textAt(g,label,l.x*s,l.y*s-13,10,'#eff0ce');}for(const b of bridges)textAt(g,b.name,riverCenter(b.y)*s,b.y*s-5,7,'#fff2bd');for(const p of garages){circle(g,p.x*s,p.y*s,7,'#d5ea91');textAt(g,'G',p.x*s,p.y*s+3,9,'#203c24');}circle(g,player.x*s,player.y*s,7,'#fff');circle(g,player.x*s,player.y*s,4,'#d86c40');textAt(g,'TY',player.x*s,player.y*s+20,11,'#fff');$('atlasGoal').textContent=job?job.target.label:'Dotknij MISJE, aby wybrać zadanie. Zielone G oznacza warsztat.';}
const officers=[],policeBullets=[];
function clearPath(a,b,r=9){const n=Math.ceil(dist(a,b)/16);for(let i=1;i<=n;i++)if(blocked(a.x+(b.x-a.x)*i/n,a.y+(b.y-a.y)*i/n,r))return false;return true;}
function walkRoute(a,b){const S=40,N=WORLD/S;const nearest=p=>{let best=null,score=Infinity;for(let x=Math.round(p.x/S)-2;x<=Math.round(p.x/S)+2;x++)for(let y=Math.round(p.y/S)-2;y<=Math.round(p.y/S)+2;y++){let q={x:x*S,y:y*S,gx:x,gy:y};if(x<1||y<1||x>=N||y>=N||blocked(q.x,q.y,9)||!clearPath(p,q))continue;let d=dist(p,q);if(d<score){score=d;best=q;}}return best;};let start=nearest(a),goal=nearest(b);if(!start||!goal)return [];const key=p=>p.gx+','+p.gy,open=[{...start,cost:0,score:dist(start,goal)}],prev=new Map(),costs=new Map([[key(start),0]]);let found=null;for(let count=0;open.length&&count<1800;count++){open.sort((a,b)=>a.score-b.score);const n=open.shift();if(n.gx===goal.gx&&n.gy===goal.gy){found=n;break;}for(const [xx,yy] of [[1,0],[-1,0],[0,1],[0,-1]]){const q={gx:n.gx+xx,gy:n.gy+yy,x:(n.gx+xx)*S,y:(n.gy+yy)*S},k=key(q),cost=n.cost+S;if(blocked(q.x,q.y,9)||!clearPath(n,q)||cost>=(costs.get(k)??Infinity))continue;costs.set(k,cost);prev.set(k,n);open.push({...q,cost,score:cost+dist(q,goal)});}}if(!found)return [];const path=[b];while(found){path.push(found);found=prev.get(key(found));}return path.reverse();}
function dispatchPatrol(){let c=null;for(let i=0;i<12&&!c;i++)c=spawnCar(cars.length,true);if(!c)return;const slots=[];for(let ix=0;ix<8;ix++)for(let iy=0;iy<8;iy++)for(let d=0;d<4;d++){if(!edgeValid(ix,iy,d))continue;const p=pathPoint(ix,iy,d),distance=dist(p,player);if(distance>480&&distance<900&&!cars.some(o=>o!==c&&dist(o,p)<85))slots.push({ix,iy,d,...p});}if(!slots.length)return;const p=slots[Math.floor(rand(0,slots.length))];c.x=p.x;c.y=p.y;c.ix=p.ix;c.iy=p.iy;c.a=p.d*Math.PI/2;c.s=70;setNext(c,p.d);if(!cars.includes(c))cars.push(c);}
function dismount(c){if(c.deployed||clock<(c.nextDismount||0)||officers.length>=12)return;c.s=0;c.deployed=0;for(const side of [-1,1]){const a=c.a+side*Math.PI/2,p={x:c.x+Math.cos(a)*31,y:c.y+Math.sin(a)*31};if(pedestrianBlocked(p.x,p.y))continue;officers.push({...p,a,home:c,hp:70,color:'#31516b',s:103,path:[],repath:0,shot:clock+2,step:0,grab:0});c.deployed++;}c.nextDismount=clock+8;}
function updateOfficers(dt){for(const c of cars)if(c.police&&c.ai&&c.hp>0&&wanted>=.5&&!player.car&&dist(c,player)<165&&Math.abs(c.s)<75)dismount(c);
for(let i=officers.length-1;i>=0;i--){const o=officers[i];if(o.hp<=0){bodies.push({x:o.x,y:o.y,a:o.a,color:o.color});if(bodies.length>120)bodies.shift();o.home.deployed=Math.max(0,(o.home.deployed||1)-1);officers.splice(i,1);continue;}const returning=wanted===0||(player.car&&dist(o,player)>430),target=returning?o.home:player;if(returning&&dist(o,o.home)<46&&o.home.hp>0){o.home.deployed=Math.max(0,(o.home.deployed||1)-1);o.home.nextDismount=clock+6;officers.splice(i,1);continue;}if(dist(o,player)>1200){o.home.deployed=Math.max(0,(o.home.deployed||1)-1);officers.splice(i,1);continue;}
let goal=target;if(!clearPath(o,target)){if(clock>o.repath){o.path=walkRoute(o,target);o.repath=clock+1.1;}while(o.path.length&&dist(o,o.path[0])<18)o.path.shift();goal=o.path[0]||o;}else o.path=[];const a=Math.atan2(goal.y-o.y,goal.x-o.x),speed=returning?80:103;for(const offset of [0,.6,-.6,1.2,-1.2]){const x=o.x+Math.cos(a+offset)*speed*dt,y=o.y+Math.sin(a+offset)*speed*dt;if(!pedestrianBlocked(x,y)){o.x=x;o.y=y;o.a=a+offset;break;}}o.step+=dt*9;
if(!returning&&dist(o,player)<23&&!player.car){o.grab+=dt;toastUntil=Math.max(toastUntil,clock+.2);$('toast').textContent='POLICJA · uciekaj sprintem!';$('toast').style.opacity='1';if(o.grab>1.8)die('Zatrzymany przez pieszy patrol.');}else o.grab=Math.max(0,o.grab-dt*2);
if(!returning&&wanted>=3&&dist(o,player)<210&&dist(o,player)>45&&clock>o.shot&&clearPath(o,player)){o.shot=clock+1.5;const a=Math.atan2(player.y-o.y,player.x-o.x)+rand(-.1,.1);policeBullets.push({x:o.x+Math.cos(a)*14,y:o.y+Math.sin(a)*14,a,life:.7});tone(125,.06,'square',.018);}
}
for(let i=policeBullets.length-1;i>=0;i--){const b=policeBullets[i];b.x+=Math.cos(b.a)*430*dt;b.y+=Math.sin(b.a)*430*dt;b.life-=dt;let hit=blocked(b.x,b.y,1);for(const c of cars)if(pedestrianContact(b.x,b.y,c,1)){damageCar(c,7);hit=true;break;}if(!player.car&&dist(b,player)<10){hurt(10);hit=true;}if(hit||b.life<=0)policeBullets.splice(i,1);}}
