function hud(){const c=player.car;$('mission').classList.toggle('job-active',!!job);$('switch').textContent=weapons[weapon].name;$('health').textContent=Math.ceil(player.hp);$('healthbar').style.width=player.hp+'%';$('healthbar').style.background=player.hp<30?'#ed8b70':'#cdeb8b';$('wanted').textContent='★ '.repeat(Math.ceil(wanted))+'☆ '.repeat(5-Math.ceil(wanted));$('money').textContent=String(cash).padStart(5,'0')+' zł';$('speed').innerHTML=(c?Math.round(Math.abs(c.s)*.48):0)+' <small>KM/H</small>';$('enter').textContent=arrest>.2?'ZATRZYMANIE '+Math.min(100,Math.round(arrest*25))+'%':c?'WYJDŹ Z AUTA':'WEJDŹ DO AUTA';$('fire').textContent=c?'GAZ':'STRZAŁ';$('brake').textContent=c?'HAMULEC':'BIEG';$('district').textContent=district(player);if(job)$('mission').innerHTML='<b>'+missionDefs.find(m=>m.id===job.id).title+'</b>'+job.target.label+'<br>'+(Number.isFinite(job.time)?Math.ceil(job.time)+' s · ':'')+(job.index+1)+' / '+missionDefs.find(m=>m.id===job.id).steps.length;else $('mission').innerHTML='<b>WARSZAWA / '+completed.size+' Z 5 MISJI</b>MISJE / F — wybór zadania.<br>Dotknij minimapy — plan miasta.';}
