function drawCar(c){const g=ctx,t=c.type;g.save();g.translate(c.x,c.y);g.rotate(c.a);rect(g,-t.w/2+4,-t.h/2+5,t.w,t.h,'#0b171960');rect(g,-t.w*.36,-t.h/2-3,t.w*.2,t.h+6,'#1a2120');rect(g,t.w*.2,-t.h/2-3,t.w*.2,t.h+6,'#1a2120');rect(g,-t.w/2,-t.h/2,t.w,t.h,c.hp<=0?'#333c38':c.color);rect(g,-t.w/2+3,-t.h/2+2,t.w-7,2,'#fff4');rect(g,-t.w*.15,-t.h*.40,t.w*.37,t.h*.80,'#29434b');rect(g,-t.w*.06,-t.h*.40,t.w*.17,t.h*.80,c.hp<=0?'#464a43':c.color);rect(g,-t.w*.36,-t.h*.34,t.w*.15,t.h*.68,'#344a4e');if(t===types[4]){rect(g,-t.w*.44,-t.h*.45,t.w*.58,t.h*.9,'#a7a89b');for(let x=-t.w*.4;x<t.w*.1;x+=7)rect(g,x,-t.h*.4,1,t.h*.8,'#777d73');}if(t===types[7]){for(let x=-28;x<28;x+=10){rect(g,x,-t.h/2,7,3,'#263e43');rect(g,x,t.h/2-3,7,3,'#263e43');}}if(t===types[3])rect(g,-4,-4,8,8,'#edce63');if(t===types[8]){rect(g,-7,-2,12,4,'#d4634b');rect(g,-3,-6,4,12,'#d4634b');}if(c.police){rect(g,-12,-t.h/2,10,t.h,'#253b47');rect(g,-3,-8,5,8,Math.sin(clock*12)>0?'#f57863':'#8d4946');rect(g,-3,0,5,8,Math.sin(clock*12)<0?'#85bdf1':'#48618b');}rect(g,t.w/2-2,-t.h/2+3,3,4,'#f1e7bd');rect(g,t.w/2-2,t.h/2-7,3,4,'#f1e7bd');rect(g,-t.w/2,-t.h/2+3,2,4,'#c4543c');rect(g,-t.w/2,t.h/2-7,2,4,'#c4543c');if(c.hp<30){circle(g,-t.w*.25,0,8+Math.sin(clock*5)*3,'#262b2780');}g.restore();}
